def solve(grid, d):
    n, m = len(grid), len(grid[0])
    cells = [(grid[i][j], i, j) for i in range(n) for j in range(m)]
    s = min(cells); e = max(cells)
    @lru_cache(None)
    def f(i, j):
        if (i, j) == (e[1], e[2]): return 1
        t = 0
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a, b = i+di, j+dj
            if 0 <= a < n and 0 <= b < m and 0 < grid[a][b]-grid[i][j] <= d:
