def solve(n, sentinels):
    bad = set()
    for x, y in sentinels:
        for dx in (-1,0,1):
            for dy in (-1,0,1): bad.add((x+dx, y+dy))
    s, t = (0, n//2), (n-1, n//2)
    if s in bad or t in bad: return [0, 0]
    dist = {s: 1}; cnt = {s: 1}; q = deque([s])
    while q:
        c = q.popleft()
        for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
            v = (c[0]+dx, c[1]+dy)
            if not (0 <= v[0] < n and 0 <= v[1] < n) or v in bad: continue
            if v not in dist:
                dist[v] = dist[c]+1; cnt[v] = cnt[c]; q.append(v)
            elif dist[v] == dist[c]+1:
                cnt[v] += cnt[c]
    if t not in dist: return [0, 0]
    return [cnt[t], dist[t]]

def solve(grid):
    if not grid or not grid[0]: return -1
    n, m = len(grid), len(grid[0])
    empties = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == '.']
    if not empties: return -1
    best = [10**9]
    used = set()      # cells occupied by squares (any cell incl. outside)
    covered = set()
    def dfs(cnt):
        if cnt >= best[0]: return
        first = next(((i, j) for (i, j) in empties if (i, j) not in covered), None)
        if first is None:
            best[0] = cnt; return
        i, j = first
        for ci in (i-1, i, i+1):
            for cj in (j-1, j, j+1):
                if not (0 <= ci < n and 0 <= cj < m) or grid[ci][cj] != '.': continue
                sq = [(a, b) for a in (ci-1, ci, ci+1) for b in (cj-1, cj, cj+1)]
                if any(c in used for c in sq): continue
                for c in sq: used.add(c)
                newly = [c for c in sq if c not in covered and 0 <= c[0] < n and 0 <= c[1] < m and grid[c[0]][c[1]] == '.']
                for c in newly: covered.add(c)
                dfs(cnt+1)
                for c in newly: covered.discard(c)
                for c in sq: used.discard(c)
    dfs(0)
    return -1 if best[0] == 10**9 else best[0]

def solve(s):
    c = Counter(s); keys = sorted(c)
    @lru_cache(None)
    def f(counts, last):
        if sum(counts) == 0: return 1
        t = 0
        for i, k in enumerate(counts):
            if k and i != last:
                nc = list(counts); nc[i] -= 1
                t += f(tuple(nc), i)
        return t
    return f(tuple(c[k] for k in keys), -1)

