def solve(nodes, relations, myId, maxHop):
    inter = {x[0]: x[1:] for x in nodes}
    g = defaultdict(list)
    for a, b in relations: g[a].append(b)
    mine = inter.get(myId, [])
    seen = {myId}; q = deque([(myId, 0)]); out = []
    while q:
        u, h = q.popleft()
        if h == maxHop: continue
        for v in g[u]:
            if v in seen: continue
            seen.add(v); q.append((v, h+1))
