        for p in parts[1:]:
            if '=' in p:
                a, b = p.split('=', 1); kv[a] = b
        rid = val(kv, 'rule_id')
        if op == 'add_rule':
            idx = val(kv, 'rule_index')
            if rid is None or idx is None or rid in rules: fail += 1
            else: rules[rid] = idx
        elif op == 'mod_rule':
            idx = val(kv, 'rule_index')
            if rid is None or idx is None or rid not in rules or rules[rid] == idx: fail += 1
