        if not keys: out.add(tuple(sorted(acc))); return
        x = keys[0]
        if c[x] >= 3:
            c[x] -= 3; melds(c, acc + [('K', x)], out); c[x] += 3
        s, p = x
        y, z = (s, p+1), (s, p+2)
        if p <= 7 and c.get(y, 0) > 0 and c.get(z, 0) > 0:
