def solve(pre, ino, node):
    if not (2 <= len(pre) <= 26) or len(pre) != len(ino): return ""
    if not all('A' <= c <= 'Z' for c in pre + ino): return ""
    if len(set(pre)) != len(pre) or set(pre) != set(ino): return ""
    pos = {c: i for i, c in enumerate(ino)}
    it = iter(pre)
    def build(l, r):
        if l > r: return None
        c = next(it); m = pos[c]
        if not (l <= m <= r): raise ValueError
        return [c, build(l, m-1), build(m+1, r)]
    try:
        root = build(0, len(ino)-1)
    except (ValueError, StopIteration):
        return ""
    if root[0] != node:
        def walk(par):
            for side in (1, 2):
                ch = par[side]
                if ch is None: continue
                if ch[0] == node:
                    if ch[1] is None and ch[2] is None: par[side] = None
                    elif side == 1: par[side] = ch[1]
                    else: par[side] = ch[2]
                    return True
                if walk(ch): return True
            return False
        walk(root)
    out = []
    def post(nd):
        if nd: post(nd[1]); post(nd[2]); out.append(nd[0])
    post(root)
    return ''.join(out)

