def solve(n, m, k, a):
    NEG = float('-inf')
    dp = [[NEG]*(m+1) for _ in range(n+1)]
    for i in range(n+1): dp[i][0] = 0
    for i in range(1, n+1):
        for j in range(1, m+1):
            dp[i][j] = dp[i-1][j]
            prev = dp[max(0, i-k)][j-1] if j > 1 else 0
            if j == 1 or i-k >= 1:
                if prev != NEG: dp[i][j] = max(dp[i][j], prev + a[i-1])
    return dp[n][m] if dp[n][m] != NEG else 0

